# DK VHL.  Vojens - Haderslev
#
let vh = path("d3.dk.vhl");

with detail = 4, railway = :first :museum {
    with link = "line.dk.VHL" {
        track(:station,
                vh[:voj.yh - 0.1dl, :voj.yh] >> 3.5mo
            ..  vh[:voj.xh, :voj.xh + 0.1dl]
        );
        track(vh[:voj.xh, :voj.xh + 0.71km]);
        line_label(:left:s, vh[:voj.xh + 0.7km] << 0.5mt, "VHL");
        track(vh[:voj.xh + 0.69km, :sty - 0.49sw]);
    }

    with link = "point.dk.Styding", railway = :station {
        track(vh[:sty - 0.5sw, :sty + 0.5sw]);
        marker(:right :de.hp, vh[:sty] >> 0.5mt);
        station(:bottom, vh[:sty] >> 0.5mt >> 1sh + (-0.5dt, 0.7dt),
            "Styding", "VHL: 4,4"
        );
    }

    with link = "line.dk.VHL" {
        track(vh[:sty + 0.49sw, :ham - 0.49sw]);
    }

    with link = "point.dk.Hammelev-Sønderjylland", railway = :station {
        track(vh[:ham - 0.5sw, :ham + 0.5sw]);
        marker(:right :de.hp, vh[:ham] >> 0.5mt);
        marker(:right :de.exbf, vh[:ham] >> 0.5mt);
        station(:bottom, vh[:ham] >> 0.5mt >> 1.4sh + (-0.4dt, 0.8dt),
            span(:former, "Hammeleff"),
            "Hammelev",
            "VHL: 6,2"
        );
    }

    with link = "line.dk.VHL" {
        track(vh[:ham + 0.49sw, :str - 0.49sw]);
    }

    with link = "point.dk.Strengløkke", railway = :station {
        track(vh[:str - 0.5sw, :str + 0.5sw]);
        marker(:right :de.hp, vh[:str] >> 0.5mt);
        station(:bottom, vh[:str] >> 0.5mt >> 1sh >> 0.7dt,
            "Strengløkke", "VHL: 10,0"
        );
    }

    with link = "line.dk.VHL" {
        track(vh[:str + 0.49sw, :str + 1.01km]);
        line_label(:right:n, vh[:str + 1km] >> 0.5mt, (0.5dt, 0dt), "VHL");
        track(vh[:str + 0.99km, :hav.ys + 0.1dl]);
    }

    with link = "point.dk.Haderslev-Vest", railway = :station {
        track(vh[:hav.ys, :hav + 50m]);
        marker(:right :de.bf, vh[:hav] >> 0.5mt);
        label(vh[:hav] + (0dt, -100m) + (-4dt, -1dt),
            vbox(:left:bottom,
                span(:former, "Hadersleben Stsbf"),
                span(:former, "Haderslev"),
                span(:former, "Haderslev Vest"),
                span(:former, "Haderslev H"),
                span(:bold, "Haderslev Vest"),
                hbox(:center:top :xsmall,
                    vbox(:right:top, span(:former, "HSB: "), "VHL: "),
                    vbox(:sep:top,
                        hbox(:sep:top :former, "1,", anchor(), "2"),
                        hbox(:sep:top, "11,", anchor(), "9")
                    )
                )
            )
        );
    }
}

with detail = 4, railway = :first :removed {
    with link = "line.dk.VHL" {
        track(vh[:hav + 49m, :hab - 0.49sw]);
    }

    with link = "point.dk.Haderslev-By", railway = :station {
        track(vh[:hab - 0.5sw, :hab + 0.5sw]);
        marker(:right :de.bf, vh[:hab] >> 0.5mt);
        station(:bottom :right_align, vh[:hab] >> 0.5mt >> 1sh + (6dt, 0.5dt),
            "Haderslev By", "VHL: 12,8 "
        );
    }

    with link = "line.dk.VHL" {
        track(vh[:hab + 0.49sw, :had - 0.49sw]);
    }

    with link = "point.dk.Haderslev-Amtsb", railway = :station {
        track(vh[:had - 0.5sw, :had + 350m]);
        marker(:right :de.bf, vh[:had] >> 0.5mt);
        station(:top :left_align, vh[:had] << 0.5mt + (-1.5dt, -0.5dt),
            vbox(:left:base,
                span(:former, "Hadersleben Klbf"),
                span(:former, "Haderlev Amtsb")
            ),
            span(:bold, "Haderslev By"),
            hbox(:center:top,
                vbox(:right:top,
                    span(:former, "HSB: "),
                    "VHL: ",
                    "HCF: ",
                    "HVA: "
                ),
                vbox(:sep:top,
                    hbox(:sep:base :former, "0,", anchor(), "0"),
                    hbox(:sep:base, "13,", anchor(), "3"),
                    hbox(:sep:base, "1,", anchor(), "2"),
                    hbox(:sep:base, "0,", anchor(), "0")
                )
            )
        );
    }
}

